 * @param {object} options.collection Required, collection
 * @param {Number|String} id Required, app id
 * @returns {Promise}
 */
export function editCollection(options, id) {
  return put({
    id,
    token: options.token,
    url: options.url,
    api: `collections/${options.collectionid}`,
    obj: options.collection
  });
}

