 * @param {object} options.customstatus Required, custom status
 * @param {Number|String} id Required, app id
 * @returns {Promise}
 */
export function editCustomStatus(options, id) {
  return put({
    id,
    token: options.token,
    url: options.url,
    api: `custom_statuses/${options.permalink}`,
    obj: options.customstatus
  });
}

