 *        valueid: '1'
 *      }).then(response => {
 *        console.info(response.data);
 *      }).catch(err => {
 *        console.error(err);
 *      });
 * Output:
 *
 *      {
 *        "id": 1,
 *        "variant_field_id": 1,
 *        "value": "some variant field value"
 *      }
 *
 *      insales.getVariantFieldValue({
 *        token: '1234567890',
