 * @param {object} options.warehouse Required, warehouse
 * @param {Number|String} id Required, app id
 * @returns {Promise}
 */
export function editWarehouse(options, id) {
  return put({
    id,
    token: options.token,
    url: options.url,
    api: `warehouses/${options.warehouseid}`,
    obj: options.warehouse
  });
}

