 * @param {Number|String} options.widgetId Required, widget id
 * @param {Number|String} id Required, app id
 * @returns {Promise}
 */
export function removeWidgetType(options, id) {
  return remove({
    id,
    token: options.token,
    url: options.url,
    api: `themes/${options.theme}/widget_types/${options.widgetId}`
  });
}

